INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Travailler avec un créateur de contenu à La Réunion : choisir, cadrer, respecter la loi', 'createurs-contenu-reunion', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'Réseaux sociaux', 'Une vidéo d''un créateur local peut remplir une salle, ou ne rien rapporter. Les formes de collaboration, cinq étapes pour choisir le bon profil et ce qu''impose la loi du 9 juin 2023.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Travailler avec un créateur de contenu local peut faire connaître une entreprise auprès d''un public qui lui fait confiance, à condition de choisir quelqu''un dont l''audience ressemble à vos clients.</li> <li>Regardez l''engagement réel et la zone géographique de l''audience plutôt que le nombre d''abonnés.</li> <li>Depuis la loi du 9 juin 2023, toute promotion rémunérée ou avec avantage doit porter la mention « Publicité » ou « Collaboration commerciale », et le contrat doit être écrit au-delà d''un montant fixé par décret.</li> </ul> </div> <p>Un restaurant qui affiche complet après la vidéo d''un créateur réunionnais, une boutique dont un produit part en rupture le lendemain d''une story : ces histoires circulent, et donnent envie d''essayer. Mais beaucoup de collaborations ne rapportent rien, faute d''avoir choisi le bon profil ou fixé un objectif.</p> <p>Voici comment choisir un créateur de contenu, préparer la collaboration et respecter le cadre légal, sans y laisser son budget.</p> <h2>Les formes de collaboration</h2> <table class="table-article"> <thead><tr><th>Forme</th><th>Principe</th><th>Pour qui</th></tr></thead> <tbody> <tr><td>Invitation ou produit offert</td><td>Le créateur découvre votre offre et en parle s''il le souhaite</td><td>Restaurants, activités, hébergements, produits à tester</td></tr> <tr><td>Prestation rémunérée</td><td>Un nombre défini de publications ou de vidéos, contre paiement</td><td>Lancement, événement, ouverture</td></tr> <tr><td>Création de contenus pour vos comptes (UGC)</td><td>Le créateur produit des vidéos que vous publiez vous-même</td><td>Entreprises qui manquent de contenus vidéo</td></tr> <tr><td>Code promo ou commission</td><td>Le créateur est payé selon les ventes réalisées avec son code</td><td>Boutiques en ligne</td></tr> </tbody> </table> <p>Dans tous ces cas, dès qu''il y a une contrepartie (argent, produit, séjour, repas), la publication est une communication commerciale et doit être signalée comme telle.</p> <h2>Choisir le bon créateur en 5 étapes</h2> <ol class="etapes"> <li><strong>Partez de vos clients.</strong> Âge, commune, centres d''intérêt : cherchez un créateur suivi par ces personnes, pas le plus connu de l''île.</li> <li><strong>Regardez l''engagement réel</strong> : commentaires sincères, réponses du créateur, partages. Un grand nombre d''abonnés avec très peu de réactions est un mauvais signe.</li> <li><strong>Demandez les statistiques de l''audience</strong>, notamment la part d''abonnés à La Réunion. Un créateur très suivi en métropole touchera peu vos clients si vous vendez sur place.</li> <li><strong>Vérifiez ses collaborations passées</strong> : sont-elles signalées comme publicité ? Le ton correspond-il à votre image ? Fait-il la promotion de produits interdits ou douteux ?</li> <li><strong>Commencez petit</strong> : une invitation ou une seule publication, avec un objectif mesurable, avant un partenariat suivi.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une table d''hôtes dans les Hauts de Saint-Paul</p> <p>Plutôt qu''une créatrice très suivie mais centrée sur la mode, les gérants invitent un créateur qui filme des balades et des adresses de l''Ouest, avec une audience surtout réunionnaise. Ils conviennent par écrit d''un repas offert pour deux, d''une vidéo courte et d''une story, avec la mention « Collaboration commerciale ». Un code de réservation dédié leur permet de compter les tables venues grâce à la vidéo.</p> </div> <h2>Ce que dit la loi</h2> <ul class="checklist"> <li><strong>La mention obligatoire</strong> : « Publicité » ou « Collaboration commerciale », claire, lisible et identifiable sur l''image ou la vidéo, pendant toute la promotion.</li> <li><strong>Le contrat écrit</strong> : la loi impose un contrat écrit entre l''annonceur et le créateur, avec des clauses obligatoires, lorsque la rémunération ou la valeur des avantages dépasse un montant fixé par décret.</li> <li><strong>Une responsabilité partagée</strong> : l''annonceur, son éventuel agent et le créateur sont solidairement responsables des dommages causés aux tiers dans l''exécution du contrat.</li> <li><strong>Des promotions interdites ou encadrées</strong> : certains produits et services ne peuvent pas être promus par un créateur ou sont strictement encadrés. Vérifiez votre secteur avant de vous lancer.</li> </ul> <h2>Préparer la collaboration</h2> <ol class="etapes"> <li><strong>Un brief court</strong> : ce que vous proposez, le message principal, ce qu''il ne faut pas dire, les dates.</li> <li><strong>La liberté de ton</strong> du créateur : c''est elle qui rend le contenu crédible. Évitez de lui imposer un texte publicitaire.</li> <li><strong>Les droits d''utilisation</strong> : pouvez-vous republier la vidéo sur vos comptes, ou l''utiliser dans une publicité ? Écrivez-le dans l''accord.</li> <li><strong>La mesure</strong> : un code promo, un lien suivi ou une question « comment nous avez-vous connus ? » au moment de la réservation.</li> </ol> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Une vidéo courte au format Reel, TikTok ou Short coûte 190 €, si vous préférez produire vos propres contenus. Le diagnostic gratuit permet de voir si une collaboration avec un créateur a du sens pour votre activité.</p> <p><a href="/tarifs" class="encadre-lien">Voir les tarifs</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Un repas offert compte-t-il comme une rémunération ?</h3> <p>Oui, c''est un avantage en nature. La publication qui en parle doit porter la mention « Publicité » ou « Collaboration commerciale ».</p> <h3>Combien coûte un créateur de contenu ?</h3> <p>Il n''y a pas de tarif officiel : cela dépend de l''audience, du format et du nombre de publications. Demandez plusieurs devis et comparez sur la base de l''audience réunionnaise réelle, pas du nombre total d''abonnés.</p> <h3>Que faire si la vidéo ne me plaît pas ?</h3> <p>Prévoyez dans l''accord une relecture pour les erreurs de fait (prix, horaires, adresse). Pour le reste, le ton du créateur fait partie de ce que vous achetez : choisissez-le en connaissance de cause.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000047663185" target="_blank" rel="noopener">Légifrance : loi n° 2023-451 du 9 juin 2023 visant à encadrer l''influence commerciale</a>.</li> <li><a href="https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000050456412" target="_blank" rel="noopener">Légifrance : ordonnance n° 2024-978 du 6 novembre 2024 modifiant la loi du 9 juin 2023</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Créateur de contenu à La Réunion : bien collaborer', 'Choisir un créateur de contenu local, préparer la collaboration et respecter la loi sur l''influence commerciale : mention obligatoire et contrat écrit.', 'créateur de contenu Réunion, influenceur Réunion, collaboration commerciale, loi influence commerciale, UGC', '/assets/images/blog/createurs-contenu-reunion.webp', '/assets/images/blog/createurs-contenu-reunion.webp', 'draft', NOW(), NOW(), 'guide')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Vendre en ligne à La Réunion : place de marché ou boutique en ligne ?', 'marketplace-reunion', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'E-commerce', 'Vendre sur Facebook, sur une grande plateforme ou sur votre propre boutique ? Les quatre canaux comparés, cinq questions pour choisir et ce que les plateformes transmettent au fisc.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Une place de marché (marketplace) vous donne accès à des acheteurs déjà présents, contre une commission et des règles imposées. Votre propre boutique en ligne vous laisse la main, mais vous devez attirer les visiteurs.</li> <li>À La Réunion, les ventes locales (retrait, livraison sur l''île) et les ventes vers la métropole ne posent pas les mêmes questions de frais et de délais.</li> <li>Les plateformes transmettent chaque année à l''administration fiscale le montant de vos ventes : déclarez-les, même occasionnelles.</li> </ul> </div> <p>Vous fabriquez des bijoux, vous revendez du matériel, vous tenez une petite épicerie fine : vendre en ligne paraît évident, mais par où commencer ? Créer un site marchand, publier sur les groupes Facebook, ouvrir une boutique sur une grande plateforme nationale ?</p> <p>Chaque canal a ses avantages et ses contraintes. Ce comparatif vous aide à choisir selon ce que vous vendez, à qui, et avec quel temps disponible.</p> <h2>Les canaux comparés</h2> <table class="table-article"> <thead><tr><th>Canal</th><th>Avantages</th><th>Limites</th><th>Pour qui</th></tr></thead> <tbody> <tr><td>Groupes et Marketplace Facebook</td><td>Gratuit ou presque, très utilisé localement, contact direct</td><td>Pas de paiement sécurisé intégré partout, beaucoup de messages à gérer, image peu professionnelle</td><td>Occasion, petites séries, tester un produit</td></tr> <tr><td>Sites de petites annonces</td><td>Large audience, publication rapide</td><td>Concurrence par le prix, options payantes pour être visible</td><td>Occasion, objets encombrants, services</td></tr> <tr><td>Grandes places de marché nationales</td><td>Très forte audience, paiement et confiance assurés</td><td>Commissions, règles strictes, concurrence nationale, logistique vers et depuis l''île</td><td>Produits qui s''expédient facilement, volume suffisant</td></tr> <tr><td>Votre boutique en ligne</td><td>Vos règles, vos prix, vos données clients, votre image</td><td>Coût de création, il faut attirer les visiteurs</td><td>Marque à construire, clientèle fidèle, offre régulière</td></tr> </tbody> </table> <h2>Les questions à se poser</h2> <ol class="etapes"> <li><strong>À qui vendez-vous ?</strong> Clients de l''île, en retrait ou livraison locale, ou acheteurs en métropole ? Les plateformes nationales n''ont d''intérêt que si vous pouvez expédier hors de l''île à un coût acceptable.</li> <li><strong>Combien vous reste-t-il sur une vente ?</strong> Prix de vente moins commission, frais de paiement, emballage, livraison et retours. Faites le calcul sur un produit réel avant de vous inscrire.</li> <li><strong>Qui garde la relation client ?</strong> Sur une grande plateforme, le client appartient surtout à la plateforme. Dans votre boutique, vous pouvez lui proposer de revenir.</li> <li><strong>Combien de temps pouvez-vous y consacrer ?</strong> Messages, photos, mises à jour du stock, expéditions. Deux canaux bien tenus valent mieux que quatre à moitié.</li> <li><strong>Quelles règles acceptez-vous ?</strong> Délais d''expédition, politique de retour, notes vendeur : lisez les conditions avant de vous engager.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une créatrice de savons artisanaux à Saint-Leu</p> <p>Elle vend d''abord dans les groupes Facebook de l''Ouest, avec retrait sur un marché le samedi. Les commandes de métropole arrivent par messages, mais les frais de port découragent une partie des acheteurs. Elle ouvre une petite boutique en ligne avec retrait local et envoi groupé vers la métropole une fois par semaine, et garde les groupes Facebook pour annoncer ses nouveautés.</p> </div> <h2>Fiscalité : ce que les plateformes déclarent</h2> <p>Selon impots.gouv.fr, les opérateurs de plateforme doivent transmettre à chaque vendeur, et à l''administration fiscale, un récapitulatif annuel : le nombre d''opérations, le montant perçu et les frais prélevés par la plateforme. Les revenus tirés de ces ventes, y compris occasionnelles, sont susceptibles d''être imposés.</p> <ul class="checklist"> <li>Si vous vendez régulièrement ce que vous fabriquez, ou ce que vous achetez pour le revendre, renseignez-vous sur le statut à adopter (la micro-entreprise par exemple).</li> <li>Les seuils de déclaration des plateformes ne disent pas si vos revenus sont imposables : c''est à vous de le vérifier.</li> <li>Gardez une trace de vos ventes et de vos frais, canal par canal.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Un site e-commerce sur mesure coûte de 2 490 € à 4 900 € selon le niveau. Le diagnostic gratuit permet de vérifier si une boutique en ligne est utile maintenant, ou si une place de marché suffit pour commencer. Voir aussi notre guide pour <a href="/blog/boutique-en-ligne-reunion">ouvrir une boutique en ligne à La Réunion</a>.</p> <p><a href="/services#sites-web" class="encadre-lien">Voir l''offre Sites web</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Peut-on cumuler une place de marché et sa propre boutique ?</h3> <p>Oui, c''est fréquent : la place de marché apporte des acheteurs, la boutique fidélise. Attention seulement au stock, qui doit être tenu à jour partout pour éviter de vendre deux fois le même article.</p> <h3>Un particulier qui vend ses affaires doit-il déclarer ?</h3> <p>Pour la vente de biens d''occasion entre particuliers, la plateforme transmet vos ventes au fisc au-delà de 2 000 € ou à partir de 30 transactions dans l''année. Ces seuils ne disent pas si vos revenus sont imposables : impots.gouv.fr précise que c''est à chacun de le vérifier.</p> <h3>Comment gérer la livraison vers la métropole ?</h3> <p>Comparez les offres des transporteurs pour un colis type, indiquez clairement les frais et délais avant l''achat, et envisagez des envois groupés. Pour les produits fragiles ou lourds, la vente locale reste souvent plus rentable.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.impots.gouv.fr/revenus-de-plateformes-collaboratives-0" target="_blank" rel="noopener">impots.gouv.fr : revenus des plateformes collaboratives</a>.</li> <li><a href="https://www.impots.gouv.fr/economie-collaborative-et-plateformes-numeriques" target="_blank" rel="noopener">impots.gouv.fr : économie collaborative et plateformes numériques</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Place de marché ou boutique en ligne à La Réunion', 'Facebook, petites annonces, grandes plateformes ou boutique en ligne : comparez les canaux pour vendre depuis La Réunion et ce que déclarent les plateformes.', 'place de marché Réunion, vendre en ligne Réunion, marketplace ou site e-commerce, vendre sur Facebook Marketplace, plateformes impôts', '/assets/images/blog/marketplace-reunion.webp', '/assets/images/blog/marketplace-reunion.webp', 'draft', NOW(), NOW(), 'comparatif')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Supports imprimés et QR codes : relier le papier à vos clients en ligne', 'supports-imprimes-qr-codes', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Identité visuelle', 'Un flyer ou une vitrine peuvent mener droit à vos avis Google ou à votre réservation. Quel support pour quel usage, six étapes pour un imprimé efficace et la sécurité des QR codes.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Carte de visite, flyer, vitrine, véhicule : les supports imprimés restent utiles à La Réunion, à condition de renvoyer vers un endroit précis en ligne.</li> <li>Un QR code doit mener à une seule action utile : laisser un avis, voir le menu, réserver, appeler, rejoindre le Wi-Fi.</li> <li>Testez chaque QR code avant l''impression, et vérifiez de temps en temps que personne n''a collé un autre code par-dessus.</li> </ul> </div> <p>Le flyer posé sur le comptoir, l''autocollant sur la camionnette, la carte de visite glissée dans un sac : beaucoup de clients découvrent encore une entreprise sur papier. Le problème, c''est que ces supports ne disent souvent rien de plus que le nom et un numéro.</p> <p>Bien conçus, ils deviennent une porte vers votre fiche Google, votre page de réservation ou vos avis. Voici comment choisir les bons supports, quoi y mettre, et comment utiliser les QR codes sans piège.</p> <h2>Quel support pour quel usage</h2> <table class="table-article"> <thead><tr><th>Support</th><th>Où il agit</th><th>Ce qu''il doit faire</th></tr></thead> <tbody> <tr><td>Carte de visite</td><td>Rencontres, salons, chantiers</td><td>Donner vos coordonnées et un accès direct à votre site ou à vos réalisations</td></tr> <tr><td>Flyer ou dépliant</td><td>Boîtes aux lettres, commerces partenaires, événements</td><td>Présenter une offre précise, avec une date et un appel à l''action</td></tr> <tr><td>Vitrine et comptoir</td><td>Clients déjà dans la boutique</td><td>Faire laisser un avis, suivre vos réseaux, réserver la prochaine visite</td></tr> <tr><td>Véhicule</td><td>Sur la route et les parkings</td><td>Être lisible en trois secondes : métier, zone, numéro</td></tr> <tr><td>Ticket, facture, emballage</td><td>Après l''achat</td><td>Demander un avis, annoncer un service complémentaire</td></tr> </tbody> </table> <h2>Les QR codes utiles en boutique</h2> <ul class="checklist"> <li><strong>Demander un avis Google</strong> : Google permet de créer, depuis votre fiche, un lien ou un QR code qui ouvre directement la fenêtre d''avis.</li> <li><strong>Afficher le menu ou la carte des prix</strong>, à jour, sans réimprimer à chaque changement.</li> <li><strong>Réserver ou prendre rendez-vous</strong> en ligne. Voir <a href="/blog/prise-rendez-vous-en-ligne">la prise de rendez-vous en ligne</a>.</li> <li><strong>Ouvrir une conversation WhatsApp</strong> avec votre numéro professionnel.</li> <li><strong>Rejoindre le Wi-Fi invité</strong> sans dicter le mot de passe.</li> </ul> <h2>Créer un support efficace en 6 étapes</h2> <ol class="etapes"> <li><strong>Une action par support.</strong> Décidez ce que la personne doit faire : appeler, réserver, laisser un avis. Un flyer qui veut tout dire ne fait rien faire.</li> <li><strong>Un titre qui parle au client</strong>, pas à vous : « Climatisation en panne ? Intervention dans le Sud sous 48 h » plutôt que le seul nom de l''entreprise.</li> <li><strong>Une page d''arrivée adaptée.</strong> Le QR code mène vers une page qui correspond au support, lisible sur téléphone, et pas vers la page d''accueil générale.</li> <li><strong>Un QR code assez grand</strong>, avec une marge blanche autour et un bon contraste, accompagné d''une phrase qui dit ce qu''il ouvre (« Scannez pour réserver »). Ajoutez aussi l''adresse écrite en clair.</li> <li><strong>Testez avant d''imprimer</strong> avec plusieurs téléphones, à la distance réelle (comptoir, vitrine, arrière d''un véhicule).</li> <li><strong>Mesurez</strong> : ajoutez à l''adresse un paramètre propre à chaque support, ou utilisez une page dédiée, pour savoir dans vos statistiques quel support fait venir des visites.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un salon de coiffure à Saint-André</p> <p>La gérante imprime un chevalet pour le comptoir avec deux QR codes : « Laissez-nous un avis » (le lien d''avis de sa fiche Google) et « Réservez votre prochain rendez-vous ». Au dos des cartes de fidélité, un seul QR code vers la réservation. Chaque premier lundi du mois, elle vérifie que les chevalets n''ont pas été recouverts et que les liens fonctionnent.</p> </div> <h2>Sécurité : protéger vos QR codes</h2> <p>Un QR code ne montre pas où il mène avant d''être scanné. Des escrocs collent parfois un autre code par-dessus un code légitime, pour envoyer vers un faux site de paiement. Quelques précautions :</p> <ul class="checklist"> <li>Placez vos QR codes à l''intérieur ou sous protection quand c''est possible, et vérifiez-les régulièrement.</li> <li>Faites pointer vos codes vers votre propre nom de domaine, que les clients reconnaissent à l''ouverture.</li> <li>Ne demandez jamais un paiement ou des coordonnées bancaires sur une page ouverte par un QR code collé à l''extérieur.</li> <li>Si vous passez par un générateur de QR codes en ligne, vérifiez que le code ne dépend pas d''un abonnement qui, une fois arrêté, rendrait vos imprimés inutilisables.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>L''identité visuelle va du logo seul à 190 € à la charte complète avec brand book à 900 €. L''optimisation de la fiche Google et la collecte d''avis coûtent 390 €.</p> <p><a href="/services#identite-visuelle" class="encadre-lien">Voir l''offre Identité visuelle</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Un QR code peut-il expirer ?</h3> <p>Un QR code « statique » contient directement l''adresse et ne s''arrête jamais, tant que la page existe. Un QR code « dynamique » passe par un service intermédiaire : pratique pour changer la destination, mais il cesse de fonctionner si le service s''arrête ou si l''abonnement n''est pas payé.</p> <h3>Peut-on offrir une remise en échange d''un avis ?</h3> <p>Non. Google interdit de proposer un avantage (produit gratuit, réduction) en échange d''un avis, de sa modification ou de la suppression d''un avis négatif. Demandez simplement, au bon moment.</p> <h3>Quelle taille pour un QR code ?</h3> <p>Plus on le scanne de loin, plus il doit être grand. Sur une carte de visite, deux centimètres de côté suffisent souvent ; sur une vitrine ou un véhicule, il faut nettement plus. Le test réel avant impression reste le meilleur repère.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/business/answer/7035772?hl=fr" target="_blank" rel="noopener">Aide Fiche d''établissement Google : conseils pour obtenir plus d''avis (lien et QR code d''avis)</a>.</li> <li><a href="https://support.google.com/business/answer/3474050?hl=fr" target="_blank" rel="noopener">Aide Fiche d''établissement Google : gérer les avis client</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Supports imprimés et QR codes : le guide pratique', 'Carte de visite, flyer, vitrine, véhicule : choisir ses supports imprimés, utiliser les QR codes utiles (avis, menu, réservation) et les protéger des fraudes.', 'QR code avis Google, flyer entreprise, carte de visite QR code, supports imprimés, QR code menu restaurant', '/assets/images/blog/supports-imprimes-qr-codes.webp', '/assets/images/blog/supports-imprimes-qr-codes.webp', 'draft', NOW(), NOW(), 'guide')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at, content_type)
VALUES ('Bad buzz local : gérer un avis ou une publication qui s''emballe', 'bad-buzz-local', (SELECT id FROM service_categories WHERE slug = 'reseaux-sociaux'), 'Réseaux sociaux', 'Sur une île où tout le monde se connaît, une mauvaise expérience peut faire le tour de la commune en une soirée. Sept étapes pour garder la main, et que faire selon le type de message.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un avis très négatif, une publication virale dans un groupe Facebook local : la première heure compte, mais une réponse à chaud fait souvent plus de dégâts que le message lui-même.</li> <li>La méthode : faire des captures, comprendre ce qui s''est passé, répondre une fois, publiquement et calmement, puis régler le problème en privé.</li> <li>Un avis faux ou injurieux peut être signalé à Google. Des propos diffamatoires relèvent de la justice, avec un délai de plainte de 3 mois.</li> </ul> </div> <p>Sur une île où tout le monde se connaît, une mauvaise expérience racontée dans un groupe Facebook de quartier peut faire le tour de la commune en une soirée. Les commentaires s''ajoutent, certains n''étaient même pas clients, et le téléphone sonne avec des questions.</p> <p>La tentation est forte de répondre tout de suite, de se justifier ou de supprimer. Voici une méthode, étape par étape, pour garder la main et, souvent, ressortir de la crise avec une meilleure image.</p> <h2>Gérer la crise en 7 étapes</h2> <ol class="etapes"> <li><strong>Ne répondez pas à chaud.</strong> Prenez une heure pour lire, souffler et décider. Une réponse agressive est capturée et partagée bien plus que le message d''origine.</li> <li><strong>Faites des captures d''écran</strong> de la publication, des commentaires et des avis, avec la date et l''adresse. Ils pourront servir si un contenu est supprimé ou si vous devez agir.</li> <li><strong>Établissez les faits.</strong> Retrouvez la commande, le rendez-vous, le salarié concerné. Le client a-t-il raison, en partie ou pas du tout ?</li> <li><strong>Répondez une fois, publiquement</strong>, avec votre nom : remerciez pour le retour, reconnaissez ce qui doit l''être, sans détail personnel sur le client, et proposez de régler la situation par téléphone ou en message privé.</li> <li><strong>Réglez le problème en privé</strong> : un geste, un remboursement, une nouvelle intervention, ou au minimum une explication. Un client satisfait de la réponse modifie parfois son avis de lui-même.</li> <li><strong>Prévenez votre équipe</strong> : ce qu''on répond au téléphone et en boutique, qui s''occupe des réseaux. Une seule voix.</li> <li><strong>Corrigez la cause</strong>, puis dites-le si c''est utile : « Suite à vos retours, nous avons changé… ». C''est ce qui transforme une crise en preuve de sérieux.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un restaurant au Tampon</p> <p>Un client publie dans un groupe local la photo d''un plat servi froid, avec un texte très dur. En une soirée, plus de cent commentaires. Le gérant attend le lendemain matin, vérifie le ticket, reconnaît un service débordé ce soir-là, et répond sous la publication : excuses, explication courte, invitation à revenir. Il appelle le client, qui accepte de revenir et ajoute un commentaire plus nuancé. Le gérant renforce l''équipe du samedi soir.</p> </div> <h2>Que faire selon le type de message</h2> <table class="table-article"> <thead><tr><th>Situation</th><th>Ce qu''on fait</th></tr></thead> <tbody> <tr><td>Critique fondée, même dure</td><td>On répond, on reconnaît, on corrige. On ne supprime pas et on ne demande pas de suppression.</td></tr> <tr><td>Avis d''une personne qui n''a jamais été cliente, avis hors sujet ou injurieux</td><td>On le signale à Google depuis la fiche. Seuls les avis contraires aux règles de Google peuvent être retirés.</td></tr> <tr><td>Commentaire insultant sur votre page Facebook</td><td>On le masque ou on le supprime en restant dans les règles de la page, et on garde une capture.</td></tr> <tr><td>Accusation fausse et précise qui porte atteinte à votre réputation</td><td>On conserve les preuves et on se renseigne sur la diffamation : la plainte doit être déposée dans les 3 mois.</td></tr> </tbody> </table> <h2>Signaler un avis Google</h2> <p>Depuis votre fiche d''établissement, ouvrez les avis, choisissez « Signaler » à côté de l''avis, puis indiquez la raison. Google précise qu''il ne faut pas signaler un avis simplement parce qu''il ne vous plaît pas : seuls ceux qui enfreignent ses règles sont supprimés. L''examen prend généralement plusieurs jours, et un appel est possible si l''avis reste en ligne. Voir aussi notre guide sur les <a href="/blog/avis-google-entreprise">avis Google</a>.</p> <h2>Les réflexes à éviter</h2> <ul class="checklist"> <li>Répondre sous le coup de la colère, ou en révélant des informations sur le client.</li> <li>Supprimer toutes les critiques sur sa page : cela se voit, et relance souvent la polémique.</li> <li>Créer de faux avis positifs ou en acheter : Google l''interdit, et les avis doivent refléter une expérience réellement vécue.</li> <li>Laisser plusieurs personnes de l''équipe répondre chacune de leur côté.</li> </ul> <p>Si la crise vient d''un piratage de votre page, la priorité est de reprendre le contrôle : voir <a href="/blog/page-facebook-piratee">page Facebook piratée</a>.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Le community management, à 390 € par mois, comprend 12 publications, la modération des commentaires et un reporting. Le diagnostic gratuit permet de préparer à l''avance qui répond et comment.</p> <p><a href="/services#reseaux-sociaux" class="encadre-lien">Voir l''offre Réseaux sociaux</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Faut-il répondre à tous les avis négatifs ?</h3> <p>Oui, autant que possible. Les futurs clients lisent surtout votre réponse : elle montre comment vous traitez un problème. Une réponse courte et polie suffit.</p> <h3>Puis-je demander à un client de retirer son avis ?</h3> <p>Vous pouvez régler le problème et lui laisser la possibilité de mettre à jour son avis. En revanche, Google interdit d''offrir un avantage en échange de la modification ou de la suppression d''un avis négatif.</p> <h3>Combien de temps dure un bad buzz local ?</h3> <p>Souvent quelques jours, si l''entreprise répond bien et ne relance pas la discussion. Ce qui reste, c''est la trace écrite : d''où l''intérêt d''une réponse publique soignée.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/business/answer/4596773?hl=fr" target="_blank" rel="noopener">Aide Fiche d''établissement Google : signaler des avis inappropriés</a>.</li> <li><a href="https://support.google.com/business/answer/7035772?hl=fr" target="_blank" rel="noopener">Aide Fiche d''établissement Google : conseils pour obtenir plus d''avis (avantages interdits)</a>.</li> <li><a href="https://www.service-public.fr/particuliers/vosdroits/F32079" target="_blank" rel="noopener">Service-Public.fr : diffamation</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 9 novembre 2026.</li> </ul> </div>', 'Bad buzz local : la méthode en 7 étapes', 'Avis très négatif, publication virale dans un groupe local : répondre sans aggraver, signaler un faux avis et savoir quand parler de diffamation.', 'bad buzz, avis négatif, répondre à un avis Google, signaler un faux avis, e-réputation entreprise', '/assets/images/blog/bad-buzz-local.webp', '/assets/images/blog/bad-buzz-local.webp', 'draft', NOW(), NOW(), 'pas-a-pas')
ON CONFLICT (slug) DO NOTHING;
